import base64, struct, zlib, subprocess, os, json, re

BIN='/workspace/artifacts/target/openpgpjs'

def armor(data, label='MESSAGE'):
    b64 = base64.b64encode(data).decode()
    lines=[b64[i:i+64] for i in range(0,len(b64),64)]
    body='\n'.join(lines)
    # crc24 over raw data
    crc=crc24(data)
    crc_bytes=bytes([(crc>>16)&0xff,(crc>>8)&0xff,crc&0xff])
    return f'-----BEGIN PGP {label}-----\n\n{body}\n={base64.b64encode(crc_bytes).decode()}\n-----END PGP {label}-----\n'

def crc24(data):
    crc=0xB704CE
    for b in data:
        crc ^= (b<<16)
        for _ in range(8):
            crc <<= 1
            if crc & 0x1000000:
                crc ^= 0x1864CFB
    return crc & 0xFFFFFF

def newlen(n):
    if n<192:
        return bytes([n])
    if n<8384:
        n-=192
        return bytes([(n>>8)+192, n&0xff])
    return b'\xff'+struct.pack('>I',n)

def pkt(tag,body):
    return bytes([0xc0|tag])+newlen(len(body))+body

def literal(payload, fmt=b'b', filename=b'', date=0x6a9c2153):
